 * 通过环境变量 VITE_VCONSOLE_ENABLED 控制是否开启 vConsole（仅 H5）
 */
export function initVConsole() {
  if (import.meta.env.VITE_VCONSOLE_ENABLED !== 'true') {
    return
  }

  import('vconsole').then(({ default: VConsole }) => {
    new VConsole()
  })
}

