/**
 * vConsole 工具（仅 H5）
 * - initVConsole：随应用启动，受环境变量 VITE_VCONSOLE_ENABLED 控制
 * - showVConsole：手动唤起（如头像连点 10 下），不受环境变量限制
 */
let vConsoleInstance = null

function createVConsole() {
  if (vConsoleInstance) {
    return
  }
  import('vconsole').then(({ default: VConsole }) => {
    if (!vConsoleInstance) {
      vConsoleInstance = new VConsole()
    }
  })
}

export function initVConsole() {
  if (import.meta.env.VITE_VCONSOLE_ENABLED !== 'true') {
    return
  }
  createVConsole()
}

// 手动唤起控制台，幂等：重复调用不会创建第二个面板
export function showVConsole() {
  createVConsole()
}

