// 跳转到实名信息页面
const gotoUserInfo = () => {
  if (useUser.idNumber) {
    uni.navigateTo({
      url: "/pages/verifyUser/info",
    })
  } else {
    uni.navigateTo({
      url: "/pages/verifyUser/index",
    })
  }
}
// #ifdef H5
// 头像连点 10 下唤起控制台：每次点击都重置 2 秒定时器，超时清零；达到 10 次唤起后清零
let avatarTapCount = 0
let avatarTapTimer = null
const onAvatarTap = () => {
  avatarTapCount++
  if (avatarTapTimer) {
    clearTimeout(avatarTapTimer)
  }
  avatarTapTimer = setTimeout(() => {
    avatarTapCount = 0
    avatarTapTimer = null
  }, 2000)
  if (avatarTapCount >= 10) {
    avatarTapCount = 0
    if (avatarTapTimer) {
      clearTimeout(avatarTapTimer)
      avatarTapTimer = null
    }
    showVConsole()
  }
}
// #endif

